using System;
using System.IO;
using System.Linq;
using System.Diagnostics;
using System.Management;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using System.Security.Principal;
using System.Threading;

namespace Overdrive {
 public class AppProcess {public int Pid,Parent,Session;public long Started,Memory;public string Name,Path,Title,Sid;public override string ToString(){return Name+"  ·  "+Pid+"  ·  "+Title;}}
 public class FocusSession {public string Id,OwnerSid,Machine,Created,OldPower,NewPower,TargetPath,OldPriority,NewPriority,State;public int HostPid,TargetPid;public long TargetStarted,HostStarted;public List<string> Closed;}
 public static class Focus {
  [DllImport("advapi32.dll",SetLastError=true)]static extern bool OpenProcessToken(IntPtr h,uint access,out IntPtr token);
  [DllImport("kernel32.dll")]static extern bool CloseHandle(IntPtr handle);
  public static readonly HashSet<string> Allowed=new HashSet<string>(new[]{"chrome","msedge","firefox","comet","opera","brave","OneDrive","Teams","ms-teams","Discord","Spotify","PhoneExperienceHost","Widgets","WidgetService","CamoStudio","Slack","Zoom","Dropbox","AdobeIPCBroker","Creative Cloud"},StringComparer.OrdinalIgnoreCase);
  static readonly string[] Critical={"system","idle","registry","smss","csrss","wininit","winlogon","services","lsass","svchost","dwm","explorer","fontdrvhost","audiodg","sihost","taskhostw","conhost","dllhost","runtimebroker","securityhealth","msmpeng","mpdefender","steam","epicgames","battle.net","battlenet","riot","vgc","vgtray","anticheat","anti-cheat","easyanticheat","battleye","beservice","faceit","eaanticheat","nvidia","nvcontainer","amd","radeon","intel","rustdesk","tailscale","apextune","codex","node","powershell","pwsh","cmd","code","antigravity"};
  public static bool ProtectedName(string name){string n=name.ToLowerInvariant();return Critical.Any(x=>n==x||n.StartsWith(x,StringComparison.Ordinal));}
  static string Owner(Process p){IntPtr token;if(!OpenProcessToken(p.Handle,8,out token))return "";try{using(var identity=new WindowsIdentity(token))return identity.User.Value;}finally{CloseHandle(token);}}
  public static List<AppProcess> Snapshot(){var parents=new Dictionary<int,int>();try{using(var q=new ManagementObjectSearcher("SELECT ProcessId,ParentProcessId FROM Win32_Process"))foreach(ManagementObject x in q.Get())parents[Convert.ToInt32(x["ProcessId"])]=Convert.ToInt32(x["ParentProcessId"]);}catch{}lastParents=parents;var list=new List<AppProcess>();int session=Process.GetCurrentProcess().SessionId;foreach(var p in Process.GetProcesses()){using(p){try{if(p.SessionId!=session)continue;string name=p.ProcessName;if(p.MainWindowHandle==IntPtr.Zero&&!Allowed.Contains(name))continue;string owner=Owner(p);if(owner!=Store.Sid)continue;list.Add(new AppProcess{Pid=p.Id,Parent=parents.ContainsKey(p.Id)?parents[p.Id]:0,Session=p.SessionId,Started=p.StartTime.ToUniversalTime().Ticks,Memory=p.PrivateMemorySize64,Name=name,Path=p.MainModule.FileName,Title=p.MainWindowTitle,Sid=owner});}catch{}}}return list;}
  static Dictionary<int,int> lastParents=new Dictionary<int,int>();
  public static HashSet<int> ProtectedTree(List<AppProcess> all,int target){var parents=new Dictionary<int,int>(lastParents);foreach(var p in all)parents[p.Pid]=p.Parent;int own=Process.GetCurrentProcess().Id;var set=new HashSet<int>{target,own};foreach(int root in new[]{target,own}){int cursor=root;var seen=new HashSet<int>{cursor};for(int i=0;i<64;i++){int parent;if(!parents.TryGetValue(cursor,out parent)||parent==0||!seen.Add(parent))break;set.Add(parent);cursor=parent;}}var descendants=new HashSet<int>{target,own};bool added;do{added=false;foreach(var p in parents)if(descendants.Contains(p.Value)&&descendants.Add(p.Key))added=true;}while(added);set.UnionWith(descendants);var chosen=all.FirstOrDefault(x=>x.Pid==target);if(chosen!=null)foreach(var p in all)if(string.Equals(p.Path,chosen.Path,StringComparison.OrdinalIgnoreCase))set.Add(p.Pid);return set;}
  public static bool CanClose(AppProcess p,HashSet<int> tree,int session,string sid){if(p.Pid<=4||p.Session!=session||p.Sid!=sid||tree.Contains(p.Pid)||ProtectedName(p.Name)||!Allowed.Contains(p.Name))return false;string root=Environment.GetFolderPath(Environment.SpecialFolder.Windows)+Path.DirectorySeparatorChar;if(string.IsNullOrEmpty(p.Path)||p.Path.StartsWith(root,StringComparison.OrdinalIgnoreCase))return false;return true;}
  public static bool SameProcess(AppProcess p){try{using(var current=Process.GetProcessById(p.Pid))return current.StartTime.ToUniversalTime().Ticks==p.Started&&string.Equals(current.MainModule.FileName,p.Path,StringComparison.OrdinalIgnoreCase)&&Owner(current)==p.Sid;}catch{return false;}}
  public static string Begin(AppProcess target,List<AppProcess> selected,bool force,bool priority,Action<string> log){if(target==null||!SameProcess(target))throw new Exception("The selected game has exited or changed; refresh the process list");string active=Path.Combine(Store.Root,"active-session.json");if(File.Exists(active)){var old=Store.Load<FocusSession>(active);if(old.State=="Active"||old.State=="Recovery needed")throw new Exception("Restore the current session before starting another");}var snapshot=Snapshot();var tree=ProtectedTree(snapshot,target.Pid);int session=Process.GetCurrentProcess().SessionId;foreach(var p in selected)if(!CanClose(p,tree,session,Store.Sid))throw new Exception("Protected or unsupported process selected: "+p.Name);var data=new FocusSession{Id=Guid.NewGuid().ToString("N"),OwnerSid=Store.Sid,Machine=Environment.MachineName,Created=DateTime.UtcNow.ToString("o"),HostPid=Process.GetCurrentProcess().Id,HostStarted=Process.GetCurrentProcess().StartTime.ToUniversalTime().Ticks,TargetPid=target.Pid,TargetStarted=target.Started,TargetPath=target.Path,OldPower=Store.Power(),NewPower="8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c",State="Active",Closed=new List<string>()};using(var game=Process.GetProcessById(target.Pid))data.OldPriority=game.PriorityClass.ToString();data.NewPriority=priority?"AboveNormal":data.OldPriority;Store.Save(active,data);
   try{var si=new ProcessStartInfo(Process.GetCurrentProcess().MainModule.FileName,"--watch-session \""+active+"\""){UseShellExecute=false,CreateNoWindow=true};using(var watchdog=Process.Start(si)){if(watchdog==null)throw new Exception("Recovery watchdog could not start");}Store.SetPower(data.NewPower);using(var game=Process.GetProcessById(target.Pid)){if(game.StartTime.ToUniversalTime().Ticks!=target.Started)throw new Exception("Game process changed");if(priority)game.PriorityClass=ProcessPriorityClass.AboveNormal;}
    foreach(var candidate in selected){if(!SameProcess(candidate)){log("Skipped changed process: "+candidate.Name);continue;}try{using(var p=Process.GetProcessById(candidate.Pid)){bool requested=p.CloseMainWindow();bool exited=requested&&p.WaitForExit(1800);if(!exited&&force){if(!SameProcess(candidate))continue;p.Kill();exited=p.WaitForExit(2000);}if(exited){data.Closed.Add(candidate.Name);Store.Save(active,data);log("Closed: "+candidate.Name);}else log("Left running: "+candidate.Name+" (did not close gracefully)");}}catch(Exception e){log("Could not close "+candidate.Name+": "+e.Message);}}
    log("Focus session active. Power and priority restore when the target exits or this app closes.");return active;
   }catch{Restore(active,log);throw;}}
  public static void Restore(string file,Action<string> log){if(!File.Exists(file))return;using(var mutex=new Mutex(false,"Local\\Overdrive-Session-Restore")){if(!mutex.WaitOne(10000))throw new Exception("Session recovery is busy");try{var data=Store.Load<FocusSession>(file);if(data.OwnerSid!=Store.Sid||data.Machine!=Environment.MachineName)throw new Exception("Session belongs to another user or PC");if(data.State!="Active"&&data.State!="Recovery needed")return;bool failed=false;try{if(Store.Power().Equals(data.NewPower,StringComparison.OrdinalIgnoreCase))Store.SetPower(data.OldPower);else log("Power plan changed outside Overdrive; preserving it");}catch(Exception e){failed=true;log("Power restore failed: "+e.Message);}try{using(var p=Process.GetProcessById(data.TargetPid)){if(p.StartTime.ToUniversalTime().Ticks==data.TargetStarted&&p.PriorityClass.ToString()==data.NewPriority)p.PriorityClass=(ProcessPriorityClass)Enum.Parse(typeof(ProcessPriorityClass),data.OldPriority);}}catch(ArgumentException){}catch(Exception e){failed=true;log("Priority restore failed: "+e.Message);}data.State=failed?"Recovery needed":"Restored";Store.Save(file,data);log(failed?"Session needs recovery; see log":"Power and priority restored. Closed applications can be reopened manually.");}finally{mutex.ReleaseMutex();}}}
  public static void Watch(string file){while(true){FocusSession data;try{data=Store.Load<FocusSession>(file);}catch{return;}if(data.State!="Active")return;bool alive=true;try{using(var p=Process.GetProcessById(data.TargetPid))alive=p.StartTime.ToUniversalTime().Ticks==data.TargetStarted;using(var host=Process.GetProcessById(data.HostPid))alive=alive&&!host.HasExited&&host.StartTime.ToUniversalTime().Ticks==data.HostStarted;}catch{alive=false;}if(!alive){try{Restore(file,s=>File.AppendAllText(Path.Combine(Path.GetDirectoryName(file),"recovery.log"),DateTime.UtcNow.ToString("o")+" "+s+Environment.NewLine));}catch{}return;}Thread.Sleep(2000);}}
 }
}
